// #6a98bd (עבר QA 25.10; решение пользователя 20.10): «עריכת הזמנה» — «+» останавливается на доступном остатке; ввод 3/5/10 →
//   после ухода с поля «במלאי 2 בלבד — לא ניתן להזמין יותר», «שמור שינויים» не сохраняет (после «ביטול» кол-во прежнее);
//   ровно 2 сохраняется; добавление из поиска сверх остатка → «במלאי 2 בלבד מ<שם> — לא ניתן להוסיף עוד.»; товар, весь остаток
//   которого занят другим ожидающим заказом → «אין מלאי זמין ל<שם>.». Доступный остаток = физический минус другие ожидающие
//   заказы — принятое поведение (25.10). Серверная проверка (RPC, обход UI) — order-edit-server-stock.spec.ts (#929aa5).
// #428d8a (עבר QA 25.10): в «עריכת הזמנה» «+»/«−» 44×44 на 360/390/820 (сенсорная эмуляция → @iphone), не пересекаются; «−» disabled при 1.
// Данные: свои товары QA-AUTO-<tag>-<ts> (₪1, остаток «ללא מקום») + заказы клиента test «QA-AUTO-<tag>-<ts>».
// afterAll: заказы отклоняются, товары удаляются. Корзина buyer общая → @orders @data (по одному).
import { test, expect, Page, Request } from '@playwright/test';
import { auth, createStockedProduct, buyerPlaceOrder, openOrder, cleanup, header } from './_qa-order';

test.use({ storageState: auth('admin') });

const stamp = () => `${String(Date.now()).slice(-7)}${Math.floor(Math.random() * 10)}`;
const money = (n: number) => `₪${n.toFixed(2)}`.replace('.', '\\.');
/** Строка товара в карточке заказа: «<שם> — <כמות> ₪<מחיר> ₪<סה"כ>». */
const cardRow = (page: Page, p: string) => page.getByText(p, { exact: true }).first().locator('..');
const rowText = (qty: number, price: number) => new RegExp(`—\\s*${qty}\\s*${money(price)}\\s*${money(qty * price)}`);

async function openEdit(page: Page, no: string) {
  await page.getByRole('button', { name: 'עריכה', exact: true }).click();
  await expect(page.getByRole('heading', { level: 1, name: `עריכת הזמנה #${no}` })).toBeVisible({ timeout: 20_000 });
}

// ======================= #6a98bd · ord-27 =======================
test.describe('orders — עריכת הזמנה: אי אפשר לשמור או להוסיף יותר מהמלאי הזמין (#6a98bd)', () => {
  test.describe.configure({ mode: 'serial' });
  const ts = stamp();
  const A = `QA-AUTO-6a98-${ts} A`; // остаток 2, в заказе 1 ×1
  const Z = `QA-AUTO-6a98-${ts} Z`; // остаток 1, весь занят заказом 2
  let order1: string | undefined;
  let order2: string | undefined;
  const created: string[] = [];

  const qty = (page: Page) => page.getByRole('textbox', { name: `כמות — ${A}`, exact: true });
  const plus = (page: Page) => page.getByRole('button', { name: `הוספת יחידה — ${A}`, exact: true });
  const overMsg = (page: Page) => page.getByText('במלאי 2 בלבד — לא ניתן להזמין יותר', { exact: true });

  test.beforeAll(async ({ browser }) => {
    test.setTimeout(300_000);
    const ctx = await browser.newContext({ storageState: auth('admin'), locale: 'he-IL', viewport: { width: 1440, height: 900 } });
    let idA: string, idZ: string;
    try {
      const page = await ctx.newPage();
      created.push(A);
      idA = await createStockedProduct(page, A, `Q6A98-${ts}-A`, 1, 2);
      created.push(Z);
      idZ = await createStockedProduct(page, Z, `Q6A98-${ts}-Z`, 1, 1);
    } finally { await ctx.close(); }
    order1 = await buyerPlaceOrder(browser, [{ id: idA, name: A, qty: 1 }], `QA-AUTO-6a98-${ts}-1`);
    order2 = await buyerPlaceOrder(browser, [{ id: idZ, name: Z, qty: 1 }], `QA-AUTO-6a98-${ts}-2`);
  });
  test.afterAll(async ({ browser }) => {
    test.setTimeout(180_000);
    await cleanup(browser, [order1, order2], created);
  });

  test.skip('«+» נעצר ב-2; הקלדת 3 / 5 / 10 — «במלאי 2 בלבד — לא ניתן להזמין יותר», «שמור שינויים» לא שומר #6a98bd @desktop @orders @data', { annotation: { type: 'skip', description: 'временно отключено 26.10 по просьбе клиента (#e7e338, лимит остатка снят); вернуть вместе с #e02e48 — knowledge/stock-logic-snapshot-2026-10-26.md §5' } }, async ({ page }) => {
    await openOrder(page, order1!);
    await expect(header(page)).toContainText('ממתינה לאישור');
    await expect(cardRow(page, A)).toHaveText(rowText(1, 1));
    await openEdit(page, order1!);
    await expect(qty(page)).toHaveValue('1');
    await plus(page).click();
    await expect(qty(page)).toHaveValue('2');
    await expect(plus(page), '«+» останавливается на остатке 2').toBeDisabled();

    // любая запись (не GET) в Supabase во время попыток сверх остатка — провал
    const writes: string[] = [];
    const onReq = (r: Request) => {
      if (/supabase\.co\/(rest|functions)\//.test(r.url()) && r.method() !== 'GET' && !/\/rpc\/(search|get|list)/.test(r.url())) writes.push(`${r.method()} ${r.url()}`);
    };
    page.on('request', onReq);
    for (const v of ['3', '5', '10']) {
      await qty(page).fill(v);
      await qty(page).press('Tab');
      await expect(overMsg(page), `сообщение для ${v}`).toBeVisible();
      await page.getByRole('button', { name: 'שמור שינויים' }).click();
      await expect(page.getByRole('heading', { level: 1, name: `עריכת הזמנה #${order1}` }), `${v}: остаёмся в форме`).toBeVisible();
      await expect(overMsg(page)).toBeVisible();
    }
    page.off('request', onReq);
    expect(writes, 'нет запросов на сохранение').toEqual([]);

    await page.getByRole('button', { name: 'ביטול', exact: true }).click();
    await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${order1}` })).toBeVisible({ timeout: 20_000 });
    await expect(cardRow(page, A), 'в заказе прежнее количество 1').toHaveText(rowText(1, 1));
  });

  test.skip('הוספה מהחיפוש מעבר למלאי — «במלאי 2 בלבד מ… — לא ניתן להוסיף עוד.»; מוצר שכל המלאי שלו בהזמנה אחרת — «אין מלאי זמין ל….» #6a98bd @desktop @orders @data', { annotation: { type: 'skip', description: 'временно отключено 26.10 по просьбе клиента (#e7e338, лимит остатка снят); вернуть вместе с #e02e48 — knowledge/stock-logic-snapshot-2026-10-26.md §5' } }, async ({ page }) => {
    await openOrder(page, order1!);
    await openEdit(page, order1!);
    await plus(page).click();
    await expect(qty(page)).toHaveValue('2');

    const search = page.getByRole('combobox', { name: 'חיפוש מוצר להוספה להזמנה' });
    const results = page.getByRole('listbox', { name: 'תוצאות חיפוש מוצרים' });
    await search.fill(A);
    await results.getByRole('option', { name: new RegExp(A) }).first().click({ timeout: 20_000 });
    await expect(page.getByText(`במלאי 2 בלבד מ${A} — לא ניתן להוסיף עוד.`, { exact: true })).toBeVisible();
    await expect(page.getByRole('textbox', { name: `כמות — ${A}`, exact: true }), 'вторая строка A не появилась').toHaveCount(1);
    await expect(qty(page)).toHaveValue('2');

    await search.fill(Z);
    await results.getByRole('option', { name: new RegExp(Z) }).first().click({ timeout: 20_000, force: true });
    await expect(page.getByText(`אין מלאי זמין ל${Z}.`, { exact: true })).toBeVisible();
    await expect(page.getByRole('textbox', { name: `כמות — ${Z}`, exact: true }), 'строка Z не добавлена').toHaveCount(0);

    await page.getByRole('button', { name: 'ביטול', exact: true }).click();
    await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${order1}` })).toBeVisible({ timeout: 20_000 });
    await expect(cardRow(page, A)).toHaveText(rowText(1, 1));
    await expect(page.getByText(Z, { exact: true })).toHaveCount(0);
  });

  test.skip('כמות שווה למלאי (2) — נשמרת, גם אחרי רענון #6a98bd @desktop @orders @data', { annotation: { type: 'skip', description: 'временно отключено 26.10 по просьбе клиента (#e7e338, лимит остатка снят); вернуть вместе с #e02e48 — knowledge/stock-logic-snapshot-2026-10-26.md §5' } }, async ({ page }) => {
    await openOrder(page, order1!);
    await openEdit(page, order1!);
    await plus(page).click();
    await expect(qty(page)).toHaveValue('2');
    await expect(overMsg(page)).toHaveCount(0);
    await page.getByRole('button', { name: 'שמור שינויים' }).click();
    await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${order1}` })).toBeVisible({ timeout: 20_000 });
    await expect(cardRow(page, A)).toHaveText(rowText(2, 1), { timeout: 15_000 });
    await page.reload();
    await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${order1}` })).toBeVisible({ timeout: 30_000 });
    await expect(cardRow(page, A)).toHaveText(rowText(2, 1));
  });
});

// ======================= #428d8a · ord-25 (עריכת הזמנה) =======================
test.describe('orders — עריכת הזמנה: כפתורי «+»/«−» 44×44 למגע (#428d8a)', () => {
  test.describe.configure({ mode: 'serial' });
  const ts = stamp();
  const P = `QA-AUTO-428d-${ts}`;
  let orderNo: string | undefined;
  let productCreated = false;

  test.beforeAll(async ({ browser }) => {
    test.setTimeout(240_000);
    const ctx = await browser.newContext({ storageState: auth('admin'), locale: 'he-IL', viewport: { width: 1440, height: 900 } });
    let id: string;
    try {
      productCreated = true;
      id = await createStockedProduct(await ctx.newPage(), P, `Q428D-${ts}`, 1, 3);
    } finally { await ctx.close(); }
    orderNo = await buyerPlaceOrder(browser, [{ id, name: P, qty: 1 }], `QA-AUTO-428d-${ts}`);
  });
  test.afterAll(async ({ browser }) => {
    test.setTimeout(180_000);
    await cleanup(browser, [orderNo], productCreated ? [P] : []);
  });

  test('«+»/«−» בעריכת הזמנה 44×44 ולא חופפים — 360/390/820; «−» לא פעיל בכמות 1 #428d8a @iphone @orders @data', async ({ page }) => {
    type Box = { x: number; y: number; width: number; height: number };
    const overlap = (a: Box, b: Box) =>
      Math.max(0, Math.min(a.x + a.width, b.x + b.width) - Math.max(a.x, b.x)) *
      Math.max(0, Math.min(a.y + a.height, b.y + b.height) - Math.max(a.y, b.y));
    const qty = page.getByRole('textbox', { name: `כמות — ${P}`, exact: true });
    const plus = page.getByRole('button', { name: `הוספת יחידה — ${P}`, exact: true });
    const minus = page.getByRole('button', { name: `הפחתת יחידה — ${P}`, exact: true });

    await page.setViewportSize({ width: 1440, height: 900 }); // список заказов — в десктопной раскладке
    await openOrder(page, orderNo!);
    await openEdit(page, orderNo!);
    await expect(qty).toHaveValue('1');
    for (const W of [360, 390, 820]) {
      await page.setViewportSize({ width: W, height: W > 800 ? 1180 : 740 });
      await qty.scrollIntoViewIfNeeded();
      const pl = (await plus.boundingBox())!;
      const mi = (await minus.boundingBox())!;
      const q = (await qty.boundingBox())!;
      for (const [n, b] of [['«+»', pl], ['«−»', mi]] as const) {
        expect(b.width, `${W}px: ширина ${n}`).toBeGreaterThanOrEqual(43.5);
        expect(b.height, `${W}px: высота ${n}`).toBeGreaterThanOrEqual(43.5);
      }
      expect(overlap(pl, mi), `${W}px: «+» и «−» не пересекаются`).toBe(0);
      expect(overlap(pl, q), `${W}px: «+» и поле количества не пересекаются`).toBe(0);
      expect(overlap(mi, q), `${W}px: «−» и поле количества не пересекаются`).toBe(0);
      await expect(minus, `${W}px: «−» неактивна при количестве 1`).toBeDisabled();
    }
    await plus.click();
    await expect(qty).toHaveValue('2');
    await expect(minus).toBeEnabled();
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.getByRole('button', { name: 'ביטול', exact: true }).click(); // ничего не сохраняем
    await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${orderNo}` })).toBeVisible({ timeout: 20_000 });
    await expect(cardRow(page, P)).toHaveText(rowText(1, 1));
  });
});
